CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS waem;
CREATE TABLE IF NOT EXISTS waem.tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','suspended')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS waem.plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, price_minor bigint NOT NULL CHECK(price_minor>=0), currency char(3) NOT NULL DEFAULT 'SAR', interval text NOT NULL CHECK(interval IN ('monthly','yearly')), features jsonb NOT NULL DEFAULT '{}'::jsonb, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS waem.subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES waem.tenants(id), plan_id uuid NOT NULL REFERENCES waem.plans(id), status text NOT NULL DEFAULT 'trialing' CHECK(status IN ('trialing','active','past_due','canceled','expired')), start_at timestamptz NOT NULL DEFAULT now(), current_period_end timestamptz NOT NULL, price_minor bigint NOT NULL CHECK(price_minor>=0), currency char(3) NOT NULL DEFAULT 'SAR', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS waem.invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES waem.tenants(id), subscription_id uuid NOT NULL REFERENCES waem.subscriptions(id), invoice_no text NOT NULL UNIQUE, amount_minor bigint NOT NULL CHECK(amount_minor>=0), currency char(3) NOT NULL DEFAULT 'SAR', status text NOT NULL DEFAULT 'issued' CHECK(status IN ('draft','issued','paid','void')), due_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS waem.payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES waem.invoices(id), amount_minor bigint NOT NULL CHECK(amount_minor>0), provider text NOT NULL, provider_reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,provider_reference));
CREATE TABLE IF NOT EXISTS waem.reminders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES waem.invoices(id), kind text NOT NULL, scheduled_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','failed')), UNIQUE(invoice_id,kind));
CREATE TABLE IF NOT EXISTS waem.audit_events (id bigserial PRIMARY KEY, action text NOT NULL, entity_type text NOT NULL, entity_id uuid NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_subscriptions_tenant ON waem.subscriptions(tenant_id);
CREATE INDEX IF NOT EXISTS ix_invoices_tenant_status ON waem.invoices(tenant_id,status);
CREATE INDEX IF NOT EXISTS ix_reminders_pending ON waem.reminders(scheduled_at) WHERE status='pending';
